"""Client that posts records to the ingestion API."""
import json
import os
import urllib.error
import urllib.request


def _ingestion_endpoint():
    """Return the ingestion endpoint from the environment, if set."""
    for name in ("INGESTION_ENDPOINT", "INGESTION_API_URL", "INGESTION_API"):
        value = os.environ.get(name)
        if value:
            return value
    return "http://127.0.0.1:8000/ingest"


ENDPOINT = _ingestion_endpoint()


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint,
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if 200 <= resp.status < 300:
                    accepted += 1
        except urllib.error.URLError:
            # Try the remaining records even if the API rejects this one or is
            # briefly unreachable.
            continue
    return accepted


def main():
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
